        new(TypographyRole.Body, "Arial Narrow", 9, 7.5, 10), new(TypographyRole.Data, "Arial Narrow", 8.5, 7, 9.5), new(TypographyRole.DataLabel, "Arial Narrow", 8.5, 7, 9.5, true), new(TypographyRole.Footer, "Arial Narrow", 7, 7, 7), new(TypographyRole.Roster, "Arial Narrow", 9, 7.5, 10), new(TypographyRole.RosterName, "Arial Narrow", 9, 6.5, 10)
    ], new Dictionary<SpacingRole, double> { [SpacingRole.Tight] = 3, [SpacingRole.Normal] = 6, [SpacingRole.Relaxed] = 10 }, new Dictionary<RuleRole, double> { [RuleRole.Light] = .28, [RuleRole.Normal] = .65, [RuleRole.Strong] = 1.2 }, 6.5);

    public static WeeklyGameNotesComposition Build(WeeklyPublicationSupply supply)
    {
