        var p1Regions = new[] { Region("P1.GameIdentity", "Game Information", new(body1.X, body1.Y, body1.Width, 72), CompositionFlexibility.Rigid), Region("P1.LookingBack", "Looking Back", new(body1.X, body1.Y + 78, halfWidth, 276), CompositionFlexibility.Elastic), Region("P1.Opponent", "Tonight's Opponent", new(body1.X + halfWidth + 12, body1.Y + 78, halfWidth, 150), CompositionFlexibility.Constrained), Region("P1.QuickFacts", "Minden Quick Facts", new(body1.X + halfWidth + 12, body1.Y + 234, halfWidth, 89), CompositionFlexibility.Constrained), Region("P1.StatOfWeek", "Stat of the Week", new(body1.X, body1.Y + 359, halfWidth, body1.Height - 359), CompositionFlexibility.Elastic), Region("P1.WeeklyReferences", "Weekly References", new(body1.X + halfWidth + 12, body1.Y + 329, halfWidth, body1.Height - 329), CompositionFlexibility.Elastic) };
        var p1Identity = ProjectGameIdentity(supply.Page1.Identity, p1Regions[0]); var p1LookingBack = ProjectLookingBack(supply.Page1.LookingBack, p1Regions[1]); var p1Opponent = ProjectOpponentInformation(supply.Page1, p1Regions[2]); var p1QuickFacts = ProjectQuickFacts(supply.Page1, p1Regions[3]); var p1Stat = ProjectStatOfWeek(supply.Page1, p1Regions[4]); var p1References = ProjectWeeklyReferences(supply.Page1, p1Regions[5]); var p1Traceability = ProjectTraceability(supply.Page1);
        var p1 = new Page1Composition(Context(supply.Page1, p1Regions, FitPage1(p1Identity, p1LookingBack, p1Opponent, p1QuickFacts, p1Stat, p1References, d), identity, d), p1Traceability, p1Identity, p1LookingBack, p1Opponent, p1QuickFacts, p1Stat, p1References);
        var p2Bounds = Vertical(Shell(2, supply.Page2.Context.Purpose, identity, d).BodyBounds, 5, d); var p2Schedules = new List<PublicationTable<SchedulePayload>>(); var p2Rankings = new List<PublicationTable<RankingSnapshotPayload>>();
        AddSchedule("P2.MindenSchedule", "Minden Schedule", supply.Page2.MindenSchedule, 0); AddSchedule("P2.OpponentSchedule", "Opponent Schedule", supply.Page2.OpponentSchedule, 1); AddSchedule("P2.DistrictSchedule", "District This Week", supply.Page2.DistrictSchedule, 2); AddRanking("P2.Class4APoll", "Class 4A Poll", supply.Page2.Class4APoll, 3); AddRanking("P2.DivisionIINonSelectRatings", "Division II Non-Select Ratings", supply.Page2.DivisionIINonSelectRatings, 4);
        var p2Regions = p2Schedules.Select(x => x.Region).Concat(p2Rankings.Select(x => x.Region)).ToList(); var visibleSchedules = p2Schedules.Select(ProjectSchedule).ToList().AsReadOnly(); var visibleRankings = p2Rankings.Select(ProjectRanking).ToList().AsReadOnly(); var p2 = new Page2Composition(supply.Page2, Context(supply.Page2, p2Regions, FitPage2(p2Schedules, p2Rankings, d), identity, d), p2Schedules, p2Rankings, visibleSchedules, visibleRankings);
        var p3Count = supply.Page3.OffenseSpecialTeams?.Content.Tables.Count ?? 0; var p3Bounds = Vertical(Shell(3, supply.Page3.Context.Purpose, identity, d).BodyBounds, Math.Max(1, p3Count + 3), d); var p3Tables = supply.Page3.OffenseSpecialTeams?.Content.Tables.Select((x, i) => new StatisticalTable($"P3.Stats.{i}", x, Region($"P3.Stats.{i}", x.Title, p3Bounds[i], CompositionFlexibility.Constrained, TypographyRole.Data))).ToList() ?? []; var p3Defense = Region("P3.Defense", "Defense", p3Bounds[p3Count], CompositionFlexibility.Rigid, TypographyRole.Data); var p3Player = Region("P3.PlayerOfGame", "Player of the Game", p3Bounds[p3Count + 1], CompositionFlexibility.Constrained); var p3Roster = Region("P3.RosterIdentity", "Roster Identity", p3Bounds[p3Count + 2], CompositionFlexibility.Rigid); var p3Regions = p3Tables.Select(x => x.Region).Concat([p3Defense, p3Player, p3Roster]).ToList(); var visibleIndividualStatistics = p3Tables.Select(ProjectIndividualStatistics).ToList().AsReadOnly(); var visibleDefense = ProjectDefense(supply.Page3, p3Defense); var visiblePlayer = ProjectPlayerOfGame(supply.Page3, p3Player); var visibleRoster = ProjectRosterReference(supply.Page3, p3Roster); var individualContent = supply.Page3.OffenseSpecialTeams?.Content; var p3 = new Page3Composition(supply.Page3, Context(supply.Page3, p3Regions, FitPage3(supply.Page3, p3Tables, p3Defense, p3Player, p3Roster, d), identity, d), p3Tables, p3Defense, p3Player, p3Roster, individualContent is not null, individualContent?.ProductionLabel ?? "", individualContent?.StatisticalSeason, visibleIndividualStatistics, visibleDefense, visiblePlayer, visibleRoster);
        var p4Blocks = Historical("P4", supply.Page4.CoachingHistoryBaseline?.Content.Sections, Shell(4, supply.Page4.Context.Purpose, identity, d).BodyBounds, d); var p4 = new Page4Composition(supply.Page4, Context(supply.Page4, p4Blocks.Select(x => x.Region).ToList(), FitHistorical(4, p4Blocks, d), identity, d), p4Blocks);
        var p5Blocks = Historical("P5", supply.Page5.ProgramHistoryBaseline?.Content.Sections, Shell(5, supply.Page5.Context.Purpose, identity, d).BodyBounds, d); var p5 = new Page5Composition(supply.Page5, Context(supply.Page5, p5Blocks.Select(x => x.Region).ToList(), FitHistorical(5, p5Blocks, d), identity, d), p5Blocks);
        var p6Region = Region("P6.TeamStatistics", "Team Statistics", Shell(6, supply.Page6.Context.Purpose, identity, d).BodyBounds, CompositionFlexibility.Rigid, TypographyRole.Data); var p6Table = new ComparativeStatTable("P6.TeamStatistics", ["Statistic", "Minden", "Opponent"], supply.Page6.TeamStatistics?.Content.Rows ?? [], p6Region); var p6 = new Page6Composition(supply.Page6, Context(supply.Page6, [p6Region], FitTable(6, p6Region, p6Table.Columns, p6Table.Rows.Select(x => new[] { x.Label, x.Minden, x.Opponent }).ToList(), d), identity, d), p6Table);
        var p7Items = supply.Page7.EditorialDisposition?.Content.Items ?? []; var p7Body = Shell(7, supply.Page7.Context.Purpose, identity, d).BodyBounds; var p7TitleRegion = Region("P7.PermanentTitle", Page7Title, new(p7Body.X, p7Body.Y, p7Body.Width, 30), CompositionFlexibility.Rigid, TypographyRole.Feature); var p7DescriptorRegion = Region("P7.PermanentDescriptor", Page7Descriptor, new(p7Body.X, p7TitleRegion.Bounds.Bottom + d.Spacing[SpacingRole.Tight], p7Body.Width, 18), CompositionFlexibility.Rigid, TypographyRole.Body); var p7FeatureBody = new CompositionRect(p7Body.X, p7DescriptorRegion.Bounds.Bottom + d.Spacing[SpacingRole.Normal], p7Body.Width, p7Body.Bottom - p7DescriptorRegion.Bounds.Bottom - d.Spacing[SpacingRole.Normal]); var p7Bounds = Vertical(p7FeatureBody, Math.Max(1, p7Items.Count), d); var p7Features = p7Items.Select((x, i) => new EditorialFeature(i, x, Region($"P7.Feature.{i}", x.Title, p7Bounds[i], CompositionFlexibility.Elastic, TypographyRole.Body))).ToList(); var p7Diagnostics = FitFixed(7, p7TitleRegion, Page7Title, TypographyRole.Feature, d).Concat(FitFixed(7, p7DescriptorRegion, Page7Descriptor, TypographyRole.Body, d)).Concat(p7Features.SelectMany(x => FitFeature(7, x, d))).ToList(); var p7Regions = new[] { p7TitleRegion, p7DescriptorRegion }.Concat(p7Features.Select(x => x.Region)).ToList(); var p7 = new Page7Composition(supply.Page7, Context(supply.Page7, p7Regions, p7Diagnostics, identity, d), Page7Title, Page7Descriptor, p7Features);
        var p8 = new Page8Composition(Roster(supply.Page8.Context, supply.Page8.MindenRoster, identity, d)); var p9 = new Page9Composition(Roster(supply.Page9.Context, supply.Page9.OpponentRoster, identity, d)); var p10 = new Page10Composition(Context(supply.Page10, [], [], identity, d), supply.Page10, []);
        IReadOnlyList<IGameNotesPageComposition> pages = [p1, p2, p3, p4, p5, p6, p7, p8, p9, p10]; ValidateComposition(pages, d); var diagnostics = pages.SelectMany(x => x.Context.Diagnostics).ToList(); var draft = new WeeklyGameNotesComposition(identity, d, p1, p2, p3, p4, p5, p6, p7, p8, p9, p10, pages, diagnostics, ""); return draft with { SemanticIdentity = ComputeSemanticIdentityForVerification(supply, draft) };
        void AddSchedule(string key, string title, AcceptedPublicationSection<SchedulePayload>? section, int index) => p2Schedules.Add(new(key, title, section?.Content, Region(key, title, p2Bounds[index], CompositionFlexibility.Constrained, TypographyRole.Data)));
        void AddRanking(string key, string title, AcceptedPublicationSection<RankingSnapshotPayload>? section, int index) => p2Rankings.Add(new(key, title, section?.Content, Region(key, title, p2Bounds[index], CompositionFlexibility.Constrained, TypographyRole.Data)));
    }

    private static Page2ScheduleComposition ProjectSchedule(PublicationTable<SchedulePayload> table)
    {
        var content = table.Content; var rows = content?.Games.Select(x => new Page2ScheduleRow(Owned(x.Date.ToString("M/d", CultureInfo.InvariantCulture), x.Opponent, x.Site, x.ResultOrTime), x.IsDistrictGame)).ToList() ?? [];
        return new(table.Key, table.Title, content is not null, Owned("Date", "Opponent", "Site", "Result/Time"), rows.AsReadOnly(), content is null ? Owned() : Owned(content.TeamOrGroup), table.Region);
    }
    private static Page2RankingComposition ProjectRanking(PublicationTable<RankingSnapshotPayload> table)
    {
        var content = table.Content; var rows = content?.Entries.Select(x => Row(x.Rank.ToString(CultureInfo.InvariantCulture), x.Team, x.Record, x.Value)).ToList() ?? [];
        return new(table.Key, table.Title, content is not null, Owned("Rank", "Team", "Record", "Value"), rows.AsReadOnly(), content is null ? Owned() : Owned(content.Title, content.SourceDate.ToString("MMMM d, yyyy", CultureInfo.InvariantCulture), content.SourceFooter), table.Region);
    }
    private static Page3IndividualStatisticsComposition ProjectIndividualStatistics(StatisticalTable table) => new(table.Key, table.Content.Title, IndividualRole(table.Content.Title), Owned(table.Content.Columns), table.Content.Rows.Select(x => Row([x.Label, .. x.Values])).ToList().AsReadOnly(), table.Region);
    private static Page3DefenseComposition ProjectDefense(Page3PublicationSupply page, CompositionRegion region) => new(region.Key, region.Heading, page.DefensiveTotals is not null, page.DefensiveTotalsConflict, Owned("Player", "#", "Solo", "Ast", "Total", "TFL", "Sack", "Hur", "PBU", "INT", "FF", "FR", "BEP", "BK"), (page.DefensiveTotals?.Players.Select(x => Row(DefenseRow(x))).ToList() ?? []).AsReadOnly(), region);
    private static Page3PlayerOfGameComposition ProjectPlayerOfGame(Page3PublicationSupply page, CompositionRegion region) => new(region.Key, region.Heading, page.PlayerOfGame is not null, Owned("Week", "Player", "Description"), (page.PlayerOfGame?.Content.Entries.Select(x => Row(x.Week.ToString(CultureInfo.InvariantCulture), x.Player, x.Description)).ToList() ?? []).AsReadOnly(), region);
    private static Page3RosterReferenceComposition ProjectRosterReference(Page3PublicationSupply page, CompositionRegion region) => new(region.Key, region.Heading, page.MindenRoster is not null, Owned("No.", "Player", "Gr.", "Pos."), (page.MindenRoster?.Content.Players.Select(x => Row(x.Number, DisplayName(x), x.Grade, x.Position)).ToList() ?? []).AsReadOnly(), region);
    private static Page3IndividualStatisticsRole IndividualRole(string title) => title.Trim().ToUpperInvariant() switch
    {
        "RUSHING" or "PASSING" or "RECEIVING" or "TOTAL OFFENSE" or "ALL-PURPOSE" or "ALL PURPOSE" => Page3IndividualStatisticsRole.Offense,
        "PUNTING" or "PUNT RETURNS" or "KICKOFF RETURNS" or "KICK RETURNS" or "KICKOFFS" or "FIELD GOALS" or "PAT" or "EXTRA POINTS" => Page3IndividualStatisticsRole.SpecialTeams,
        _ => Page3IndividualStatisticsRole.Unknown
    };
    private static CompositionVisibleRow Row(params string[] cells) => new(cells.ToList().AsReadOnly());
    private static IReadOnlyList<string> Owned(params string[] values) => values.ToList().AsReadOnly();
    private static IReadOnlyList<string> Owned(IEnumerable<string> values) => values.ToList().AsReadOnly();
    private static string[] DefenseRow(DefensiveStatLine x) => [x.PlayerName, x.JerseyNumber, DefensiveValue(x.Solo), DefensiveValue(x.Assisted), DefensiveValue(x.Total), DefensiveValue(x.TacklesForLoss), DefensiveValue(x.Sacks), DefensiveValue(x.QuarterbackHurries), DefensiveValue(x.PassBreakups), DefensiveValue(x.Interceptions), DefensiveValue(x.ForcedFumbles), DefensiveValue(x.FumbleRecoveries), DefensiveValue(x.BlockedExtraPoints), DefensiveValue(x.BlockedKicks)];
    private static string DefensiveValue(DefensiveSourceValue x) => x.State == DefensiveCellState.Numeric ? x.Numeric?.ToString(CultureInfo.InvariantCulture) ?? "" : x.Raw;

    private static CompositionPageContext Context(IWeeklyPublicationPage page, IReadOnlyList<CompositionRegion> regions, IReadOnlyList<CompositionDiagnostic> diagnostics, PublicationIdentity identity, PublicationDesignContract d) { var c = page.Context; var shell = Shell(c.PageNumber, c.Purpose, identity, d); var all = diagnostics.Concat(FitShell(c.PageNumber, shell, d)).Concat(c.Blockers.Select(x => new CompositionDiagnostic(c.PageNumber, x.RequirementKey, CompositionSeverity.Blocking, CompositionDiagnosticCode.UnsupportedCompositionState, x.Message))).ToList(); return new(c.PageNumber, c.Purpose, c.ProductionState, c.IsPublicationReady, shell, regions, all, c.ChangedRequirementKeys); }
    private static Page1Traceability ProjectTraceability(Page1PublicationSupply page)
    {
        var identity = new AuthorityReference(AuthorityDomain.WeeklyProject, page.Identity.ProjectId, null, null, null, null, null); var game = page.LookingBack is null ? null : new AuthorityReference(AuthorityDomain.AcceptedCompletedGame, page.LookingBack.Id, page.LookingBack.StagedReportId, page.LookingBack.ImportRecordId, page.LookingBack.ExpectedDocumentId, page.LookingBack.SourceFamilyId, page.LookingBack.AcceptedUtc); var facts = page.WeeklyFacts?.Authority; var factsReference = facts is null ? null : new AuthorityReference(AuthorityDomain.AcceptedSupplementalSection, facts.Id, facts.StagedSectionId, null, null, null, facts.AcceptedUtc); return new(identity, game, factsReference, (page.WeeklyFacts?.Evidence ?? []).ToList().AsReadOnly());
    }
    private static Page1GameIdentityComposition ProjectGameIdentity(WeeklyGameIdentity identity, CompositionRegion region) => new(identity.Opponent, identity.GameDate?.ToString("MMMM d, yyyy", CultureInfo.InvariantCulture) ?? "", identity.KickoffTime?.ToString("h:mm tt", CultureInfo.InvariantCulture) ?? "", identity.Venue, region);
    private static Page1LookingBackComposition? ProjectLookingBack(CompletedGame? game, CompositionRegion region) => game is null ? null : new(game.Opponent, game.GameDate.ToString("MMMM d, yyyy", CultureInfo.InvariantCulture), game.Site, $"Minden {game.MindenScore}, {game.Opponent} {game.OpponentScore}", game.PeriodScores.Select(x => new Page1PeriodScoreComposition(x.Order, x.Label, x.MindenPoints, x.OpponentPoints)).ToList().AsReadOnly(), game.ScoringPlays.Select(x => new Page1ScoringPlayComposition(x.Period, x.Clock, x.Team, x.Description, x.ScoreAfterPlay)).ToList().AsReadOnly(), region);
    private static Page1OpponentInformationComposition ProjectOpponentInformation(Page1PublicationSupply page, CompositionRegion region) => new((page.WeeklyFacts?.Content.OpponentFacts.Rows ?? []).Select(x => new Page1InformationRowComposition(x.Label, x.Values.ToList().AsReadOnly(), x.EvidenceId)).ToList().AsReadOnly(), region);
    private static Page1QuickFactsComposition ProjectQuickFacts(Page1PublicationSupply page, CompositionRegion region) { var f = page.WeeklyFacts?.Content; return new(f?.MindenRecord.Value ?? "", f?.OpponentRecord.Value ?? "", f?.Weather.Temperature ?? "", f?.Weather.Sky ?? "", f?.Weather.Wind ?? "", (f?.ByTheNumbers.Select(x => x.Value).ToList() ?? []).AsReadOnly(), f?.PriorSeasonSummary.Value ?? "", region); }
    private static Page1StatOfWeekComposition ProjectStatOfWeek(Page1PublicationSupply page, CompositionRegion region) => new(page.StatOfWeek.State, page.StatOfWeek.Selection?.Headline ?? "", page.StatOfWeek.Selection?.DisplayText ?? "", page.StatOfWeek.SupportingFacts.Select(x => x.Value).ToList().AsReadOnly(), page.StatOfWeek.EditorialEvidence, region);
    private static Page1WeeklyReferencesComposition ProjectWeeklyReferences(Page1PublicationSupply page, CompositionRegion region) { var f = page.WeeklyFacts?.Content; return new((f?.SeriesHistory.Select(x => x.Value).ToList() ?? []).AsReadOnly(), (f?.WinImplications.Select(x => x.Value).ToList() ?? []).AsReadOnly(), f?.SeriesExtremes.Value ?? "", f?.Storyline.Value ?? "", region); }
    private static List<CompositionDiagnostic> FitPage1(Page1GameIdentityComposition identity, Page1LookingBackComposition? lookingBack, Page1OpponentInformationComposition opponent, Page1QuickFactsComposition quickFacts, Page1StatOfWeekComposition stat, Page1WeeklyReferencesComposition references, PublicationDesignContract d)
    {
        var z = new List<CompositionDiagnostic>(); z.AddRange(FitWrapped(1, identity.Region, [$"Opponent: {identity.Opponent}", $"Date: {identity.GameDate}", $"Kickoff: {identity.KickoffTime}", $"Venue: {identity.Venue}"], TypographyRole.Body, d)); if (lookingBack is not null) z.AddRange(FitLookingBack(lookingBack, d)); z.AddRange(FitWrapped(1, opponent.Region, opponent.Rows.Select(x => $"{x.Label} {string.Join(" | ", x.Values)}"), TypographyRole.Body, d)); z.AddRange(FitWrapped(1, quickFacts.Region, [quickFacts.MindenRecord, quickFacts.OpponentRecord, quickFacts.Temperature, quickFacts.Sky, quickFacts.Wind, .. quickFacts.ByTheNumbers, quickFacts.PriorSeasonSummary], TypographyRole.Body, d)); z.AddRange(FitWrapped(1, stat.Region, stat.SupportingFacts.Concat([stat.Headline, stat.DisplayText]), TypographyRole.Body, d)); z.AddRange(FitWrapped(1, references.Region, references.SeriesHistory.Concat(references.WinImplications).Concat([references.SeriesExtremes, references.Storyline]), TypographyRole.Body, d)); return z;
    }
    private static List<CompositionDiagnostic> FitLookingBack(Page1LookingBackComposition lookingBack, PublicationDesignContract d)
    {
        var visible = new List<string> { $"Opponent: {lookingBack.PreviousOpponent}", $"Date: {lookingBack.PreviousGameDate}", $"Site: {lookingBack.PreviousGameSite}", $"Final: {lookingBack.FinalScoreResult}" };
        visible.AddRange(lookingBack.PeriodScores.Select(x => $"{x.Label}: {x.MindenPoints}-{x.OpponentPoints}")); visible.AddRange(lookingBack.ScoringPlays.Select(x => $"{x.Period} {x.Clock} {x.Team} {x.Description} {x.ScoreAfterPlay}"));
        return FitWrapped(1, lookingBack.Region, visible, TypographyRole.Body, d);
    }
    private static List<CompositionDiagnostic> FitPage2(IEnumerable<PublicationTable<SchedulePayload>> schedules, IEnumerable<PublicationTable<RankingSnapshotPayload>> rankings, PublicationDesignContract d) { var z = new List<CompositionDiagnostic>(); foreach (var t in schedules) { if (t.Content is null) z.AddRange(FitFixed(2, t.Region, t.Region.Heading, TypographyRole.SectionHeading, d)); else z.AddRange(FitTable(2, t.Region, ["Date", "Opponent", "Site", "Result/Time"], t.Content.Games.Select(x => new[] { x.Date.ToString("M/d", CultureInfo.InvariantCulture), x.Opponent + (x.IsDistrictGame ? " *" : ""), x.Site, x.ResultOrTime }).ToList(), d, [t.Content.TeamOrGroup])); } foreach (var t in rankings) { if (t.Content is null) z.AddRange(FitFixed(2, t.Region, t.Region.Heading, TypographyRole.SectionHeading, d)); else z.AddRange(FitTable(2, t.Region, ["Rank", "Team", "Record", "Value"], t.Content.Entries.Select(x => new[] { x.Rank.ToString(CultureInfo.InvariantCulture), x.Team, x.Record, x.Value }).ToList(), d, [t.Content.Title, t.Content.SourceDate.ToString("MMMM d, yyyy", CultureInfo.InvariantCulture), t.Content.SourceFooter])); } return z; }
    private static List<CompositionDiagnostic> FitPage3(Page3PublicationSupply page, IReadOnlyList<StatisticalTable> tables, CompositionRegion defense, CompositionRegion player, CompositionRegion roster, PublicationDesignContract d)
    {
        var z = new List<CompositionDiagnostic>(); var tableList = tables.ToList(); for (var i = 0; i < tableList.Count; i++) { var t = tableList[i]; var details = i == 0 && page.OffenseSpecialTeams is not null ? new[] { page.OffenseSpecialTeams.Content.ProductionLabel, page.OffenseSpecialTeams.Content.StatisticalSeason.ToString(CultureInfo.InvariantCulture) } : null; z.AddRange(FitTable(3, t.Region, t.Content.Columns, t.Content.Rows.Select(x => new[] { x.Label }.Concat(x.Values).ToArray()).ToList(), d, details)); if (IndividualRole(t.Content.Title) == Page3IndividualStatisticsRole.Unknown) z.Add(new CompositionDiagnostic(3, t.Region.Key, CompositionSeverity.Blocking, CompositionDiagnosticCode.UnsupportedCompositionState, $"Individual-statistics table identity '{t.Content.Title}' has no governed offense/special-teams semantic role.")); } if (page.DefensiveTotals is not null) z.AddRange(FitTable(3, defense, ["Player", "#", "Solo", "Ast", "Total", "TFL", "Sack", "Hur", "PBU", "INT", "FF", "FR", "BEP", "BK"], page.DefensiveTotals.Players.Select(DefenseRow).ToList(), d)); else z.AddRange(FitFixed(3, defense, defense.Heading, TypographyRole.SectionHeading, d)); if (page.PlayerOfGame is not null) z.AddRange(FitTable(3, player, ["Week", "Player", "Description"], page.PlayerOfGame.Content.Entries.Select(x => new[] { x.Week.ToString(CultureInfo.InvariantCulture), x.Player, x.Description }).ToList(), d)); else z.AddRange(FitFixed(3, player, player.Heading, TypographyRole.SectionHeading, d)); if (page.MindenRoster is not null) z.AddRange(FitTable(3, roster, ["No.", "Player", "Gr.", "Pos."], page.MindenRoster.Content.Players.Select(x => new[] { x.Number, DisplayName(x), x.Grade, x.Position }).ToList(), d)); else z.AddRange(FitFixed(3, roster, roster.Heading, TypographyRole.SectionHeading, d)); return z;
        static string[] DefenseRow(DefensiveStatLine x) => [x.PlayerName, x.JerseyNumber, V(x.Solo), V(x.Assisted), V(x.Total), V(x.TacklesForLoss), V(x.Sacks), V(x.QuarterbackHurries), V(x.PassBreakups), V(x.Interceptions), V(x.ForcedFumbles), V(x.FumbleRecoveries), V(x.BlockedExtraPoints), V(x.BlockedKicks)]; static string V(DefensiveSourceValue x) => x.State == DefensiveCellState.Numeric ? x.Numeric?.ToString(CultureInfo.InvariantCulture) ?? "" : x.Raw;
    }
    private static List<CompositionDiagnostic> FitHistorical(int page, IReadOnlyList<HistoricalReferenceBlock> blocks, PublicationDesignContract d) => blocks.SelectMany(x => FitRows(page, x.Region, x.Content.Rows, d)).ToList();
    private static List<CompositionDiagnostic> FitRows(int page, CompositionRegion region, IEnumerable<InformationRow> rows, PublicationDesignContract d) => FitWrapped(page, region, rows.Select(x => $"{x.Label} {string.Join(" | ", x.Values)}"), TypographyRole.Body, d);
