        void Object(string path, bool present) { Token("object"); Token(path); Token(present ? "present" : "null"); }
        void Nullable(string path, object? value) { Token("nullable"); Token(path); Token(value is null ? "null" : "value"); if (value is not null) Token(Format(value)); }
        void Scalar(string path, object? value) { Token("scalar"); Token(path); Token(value is null ? "null" : "value"); if (value is not null) Token(Format(value)); }
        void Token(string value) => c.Append(value.Length.ToString(CultureInfo.InvariantCulture)).Append(':').Append(value).Append('|');
        static string Format(object value) => value switch { double n => n.ToString("R", CultureInfo.InvariantCulture), IFormattable f => f.ToString(null, CultureInfo.InvariantCulture) ?? "", _ => value.ToString() ?? "" };
