    private static void ValidateDesign(PublicationDesignContract d)
    {
        if (d.PageWidth <= 0 || d.PageHeight <= 0 || d.Margin < 0 || d.Margin * 2 >= d.PageWidth || d.HeaderHeight <= 0 || d.FooterHeight <= 0 || d.TextLeading <= 0 || d.LocalFitStepPoints <= 0 || d.MinimumRosterNamePoints <= 0) throw new InvalidOperationException("The governed WP 7 design contract is invalid.");
        foreach (var role in Enum.GetValues<TypographyRole>()) { var matches = d.Typography.Where(x => x.Role == role).ToList(); if (matches.Count != 1 || matches[0].MinimumPoints <= 0 || matches[0].PreferredPoints < matches[0].MinimumPoints || matches[0].MaximumPoints < matches[0].PreferredPoints || matches[0].Family is not ("Arial Narrow" or "Impact")) throw new InvalidOperationException($"The governed typography contract for {role} is invalid."); }
        if (d.Spacing.Count != Enum.GetValues<SpacingRole>().Length || d.Spacing.Any(x => x.Value < 0) || d.Rules.Count != Enum.GetValues<RuleRole>().Length || d.Rules.Any(x => x.Value <= 0) || d.MinimumRosterNamePoints > Type(d, TypographyRole.RosterName).PreferredPoints) throw new InvalidOperationException("The governed spacing, rule, or roster contract is invalid.");
    }
    private static void ValidateComposition(IEnumerable<IGameNotesPageComposition> pages, PublicationDesignContract d) { var pageBounds = new CompositionRect(0, 0, d.PageWidth, d.PageHeight); foreach (var page in pages) { if (!pageBounds.Contains(page.Context.Shell.Header.Bounds) || !pageBounds.Contains(page.Context.Shell.Footer.Bounds) || !pageBounds.Contains(page.Context.Shell.BodyBounds) || page.Context.Regions.Any(x => x.Bounds.Width <= 0 || x.Bounds.Height <= 0 || !pageBounds.Contains(x.Bounds))) throw new InvalidOperationException($"Page {page.Context.PageNumber} contains invalid governed region geometry."); } }
